  1→import { useState, useEffect, useRef, useCallback } from 'react';
  2→
  3→const SERVER_BASE = 'http://localhost:3001';
  4→const WS_BASE = 'ws://localhost:3001';
  5→
  6→export function useOnlineGame({ serverToken, roomId }) {
  7→  const [board, setBoard] = useState(null);
  8→  const [currentTurn, setCurrentTurn] = useState(null);
  9→  const [myColor, setMyColor] = useState(null);
 10→  const [legalMoves, setLegalMoves] = useState([]);
 11→  const [moveHistory, setMoveHistory] = useState([]);
 12→  const [gameResult, setGameResult] = useState(null);
 13→  const [status, setStatus] = useState('loading'); // loading | waiting | playing | finished | error
 14→  const [room, setRoom] = useState(null);
 15→  const [error, setError] = useState(null);
 16→
 17→  const wsRef = useRef(null);
 18→  const roomIdRef = useRef(roomId);
 19→  roomIdRef.current = roomId;
 20→
 21→  const headers = useCallback(() => ({
 22→    'Content-Type': 'application/json',
 23→    'Authorization': `Bearer ${serverToken}`,
 24→  }), [serverToken]);
 25→
 26→  // Fetch room state from server
 27→  const fetchRoom = useCallback(async () => {
 28→    if (!serverToken || !roomId) return;
 29→
 30→    try {
 31→      const resp = await fetch(`${SERVER_BASE}/api/rooms/${roomId}`, {
 32→        headers: { 'Authorization': `Bearer ${serverToken}` },
 33→      });
 34→
 35→      if (!resp.ok) {
 36→        const data = await resp.json().catch(() => ({}));
 37→        setError(data.error || 'Failed to fetch room');
 38→        setStatus('error');
 39→        return;
 40→      }
 41→
 42→      const data = await resp.json();
 43→      setBoard(data.board);
 44→      setCurrentTurn(data.currentTurn);
 45→      setMyColor(data.myColor);
 46→      setLegalMoves(data.legalMoves || []);
 47→      setMoveHistory(data.moveHistory || []);
 48→      setRoom(data);
 49→
 50→      if (data.result) {
 51→        setGameResult(data.result);
 52→        setStatus('finished');
 53→      } else if (data.status === 'waiting') {
 54→        setStatus('waiting');
 55→      } else {
 56→        setStatus('playing');
 57→      }
 58→    } catch (err) {
 59→      console.error('Fetch room error:', err);
 60→      setError('Network error');
 61→      setStatus('error');
 62→    }
 63→  }, [serverToken, roomId]);
 64→
 65→  // Initial fetch
 66→  useEffect(() => {
 67→    fetchRoom();
 68→  }, [fetchRoom]);
 69→
 70→  // WebSocket connection
 71→  useEffect(() => {
 72→    if (!serverToken || !roomId) return;
 73→
 74→    const ws = new WebSocket(`${WS_BASE}/api/rooms/${roomId}/ws?token=${serverToken}`);
 75→    wsRef.current = ws;
 76→
 77→    ws.onmessage = (event) => {
 78→      const msg = JSON.parse(event.data);
 79→
 80→      switch (msg.event) {
 81→        case 'joined':
 82→          // Our own connection confirmed
 83→          break;
 84→
 85→        case 'join':
 86→          // Another player joined - game is starting
 87→          setStatus('playing');
 88→          fetchRoom();
 89→          break;
 90→
 91→        case 'move':
 92→          // Opponent made a move - re-fetch full state for legal moves
 93→          fetchRoom();
 94→          break;
 95→
 96→        case 'gameOver':
 97→          setGameResult(msg.data.result);
 98→          setStatus('finished');
 99→          fetchRoom();
100→          break;
101→
102→        case 'playerConnected':
103→        case 'playerDisconnected':
104→          // Could show connection indicators later
105→          break;
106→      }
107→    };
108→
109→    ws.onerror = (err) => {
110→      console.error('WebSocket error:', err);
111→    };
112→
113→    ws.onclose = () => {
114→      wsRef.current = null;
115→    };
116→
117→    return () => {
118→      ws.close();
119→      wsRef.current = null;
120→    };
121→  }, [serverToken, roomId, fetchRoom]);
122→
123→  // Submit a move via REST
124→  const submitMove = useCallback(async (uciStr) => {
125→    if (!serverToken || !roomId) return { ok: false };
126→
127→    try {
128→      const resp = await fetch(`${SERVER_BASE}/api/rooms/${roomId}/move`, {
129→        method: 'POST',
130→        headers: headers(),
131→        body: JSON.stringify({ move: uciStr }),
132→      });
133→
134→      const data = await resp.json();
135→
136→      if (!resp.ok) {
137→        console.error('Move rejected:', data.error);
138→        return { ok: false, error: data.error };
139→      }
140→
141→      // Re-fetch to get updated board and legal moves
142→      await fetchRoom();
143→
144→      if (data.gameOver) {
145→        setGameResult(data.result);
146→        setStatus('finished');
147→      }
148→
149→      return { ok: true, data };
150→    } catch (err) {
151→      console.error('Submit move error:', err);
152→      return { ok: false, error: 'Network error' };
153→    }
154→  }, [serverToken, roomId, headers, fetchRoom]);
155→
156→  // Get valid target squares for a source square from server legal moves
157→  const getValidMovesForSquare = useCallback((sourceIndex) => {
158→    const cols = 'abcdefgh';
159→    const sourceFile = cols[sourceIndex % 8];
160→    const sourceRank = 8 - Math.floor(sourceIndex / 8);
161→    const sourceStr = sourceFile + sourceRank;
162→
163→    const targets = [];
164→    for (const uci of legalMoves) {
165→      if (uci.startsWith(sourceStr)) {
166→        const targetFile = uci[2];
167→        const targetRank = parseInt(uci[3]);
168→        const targetCol = cols.indexOf(targetFile);
169→        const targetRow = 8 - targetRank;
170→        const targetIndex = targetRow * 8 + targetCol;
171→        targets.push(targetIndex);
172→      }
173→    }
174→
175→    // Deduplicate (promotions create multiple moves for same target)
176→    return [...new Set(targets)];
177→  }, [legalMoves]);
178→
179→  return {
180→    board,
181→    currentTurn,
182→    myColor,
183→    legalMoves,
184→    moveHistory,
185→    gameResult,
186→    status,
187→    error,
188→    room,
189→    submitMove,
190→    getValidMovesForSquare,
191→    fetchRoom,
192→  };
193→}
