import { useState, useEffect, useRef } from 'react';

const WS_BASE = 'ws://localhost:3001';

function WaitingRoom({ inviteCode, serverToken, roomId, onGameStart, onCancel }) {
  const [copied, setCopied] = useState(false);
  const wsRef = useRef(null);

  useEffect(() => {
    if (!serverToken || !roomId) return;

    const ws = new WebSocket(`${WS_BASE}/api/rooms/${roomId}/ws?token=${serverToken}`);
    wsRef.current = ws;

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.event === 'join') {
        onGameStart(roomId);
      }
    };

    ws.onerror = (err) => {
      console.error('WaitingRoom WS error:', err);
    };

    ws.onclose = () => {
      wsRef.current = null;
    };

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [serverToken, roomId, onGameStart]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(inviteCode);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback for non-HTTPS
      const el = document.createElement('textarea');
      el.value = inviteCode;
      document.body.appendChild(el);
      el.select();
      document.execCommand('copy');
      document.body.removeChild(el);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="new-game-setup waiting-room">
      <h2>Waiting for Opponent</h2>

      <p className="waiting-subtitle">Share this code with your opponent:</p>

      <div className="invite-code-display">
        <span className="invite-code">{inviteCode}</span>
        <button className="copy-button" onClick={handleCopy}>
          {copied ? 'Copied!' : 'Copy'}
        </button>
      </div>

      <p className="waiting-hint">The game will start automatically when they join.</p>

      <div className="setup-actions">
        <button className="setup-back" onClick={onCancel}>Cancel</button>
      </div>
    </div>
  );
}

export default WaitingRoom;

import { useState, useEffect } from 'react';

import './App.css';
import Chessboard from './Chessboard';
import GameList from './components/GameList';
import AuthGate from './components/AuthGate';
import GameSetup from './components/GameSetup';
import JoinGame from './components/JoinGame';
import WaitingRoom from './components/WaitingRoom';
import OnlineChessboard from './components/OnlineChessboard';
import { createGame, saveGame, loadGame, markGamePublished, setCurrentUser } from './utils/gameManager';
import { usePasskeyAuth } from './hooks/usePasskeyAuth';
import { usePasskeyPublish } from './hooks/usePasskeyPublish';
import { useServerAuth } from './hooks/useServerAuth';

const SERVER_BASE = 'http://localhost:3001';

// Persist/restore online game session across reloads
const SS_ONLINE_KEY = 'online_game_session';

function saveOnlineSession(view, roomId, inviteCode) {
  if (view === 'online' || view === 'waiting') {
    sessionStorage.setItem(SS_ONLINE_KEY, JSON.stringify({ view, roomId, inviteCode }));
  } else {
    sessionStorage.removeItem(SS_ONLINE_KEY);
  }
}

function loadOnlineSession() {
  try {
    const raw = sessionStorage.getItem(SS_ONLINE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

function App() {
  const saved = loadOnlineSession();
  const [view, setView] = useState(saved?.view || 'list');
  const [activeGame, setActiveGame] = useState(null);
  const [publishStatus, setPublishStatus] = useState(null);

  // Online game state
  const [onlineRoomId, setOnlineRoomId] = useState(saved?.roomId || null);
  const [onlineInviteCode, setOnlineInviteCode] = useState(saved?.inviteCode || null);

  const passkey = usePasskeyAuth();
  const serverAuth = useServerAuth({
    isAuthenticated: passkey.isAuthenticated,
    account: passkey.account,
    username: passkey.username,
  });
  const { publishGame: passkeyPublish } = usePasskeyPublish({
    account: passkey.account,
    credentialId: passkey.credentialId,
    rawId: passkey.rawId,
  });

  // Persist online session to sessionStorage on state changes
  useEffect(() => {
    saveOnlineSession(view, onlineRoomId, onlineInviteCode);
  }, [view, onlineRoomId, onlineInviteCode]);

  // Scope game storage to the authenticated user
  useEffect(() => {
    if (passkey.isAuthenticated && passkey.account) {
      setCurrentUser(passkey.account);
    } else {
      setCurrentUser(null);
    }
  }, [passkey.isAuthenticated, passkey.account]);

  const handleLogout = () => {
    passkey.logout();
    serverAuth.logout();
    setActiveGame(null);
    setPublishStatus(null);
    setOnlineRoomId(null);
    setOnlineInviteCode(null);
    setView('list');
  };

  const handleNewGame = () => {
    setView('setup');
  };

  // Local AI game start
  const handleStartLocal = (color) => {
    const engineColor = color === 'white' ? 'black' : 'white';
    const game = createGame(engineColor);
    setActiveGame(game);
    setView('playing');
  };

  // Online game start
  const handleStartOnline = async (color) => {
    if (!serverAuth.serverToken) return;

    try {
      const resp = await fetch(`${SERVER_BASE}/api/rooms`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${serverAuth.serverToken}`,
        },
        body: JSON.stringify({ color, opponent: 'human' }),
      });

      const data = await resp.json();
      if (!resp.ok) {
        console.error('Create room failed:', data.error);
        return;
      }

      setOnlineRoomId(data.roomId);
      setOnlineInviteCode(data.inviteCode);
      setView('waiting');
    } catch (err) {
      console.error('Create room error:', err);
    }
  };

  const handleJoinGame = () => {
    setView('join');
  };

  const handleJoined = (roomId) => {
    setOnlineRoomId(roomId);
    setView('online');
  };

  const handleWaitingGameStart = (roomId) => {
    setOnlineRoomId(roomId);
    setView('online');
  };

  const handleResumeGame = (gameId) => {
    const game = loadGame(gameId);
    if (game) {
      setActiveGame(game);
      setView('playing');
    }
  };

  const handleSave = (state) => {
    if (!activeGame) return;
    saveGame({ ...state, id: activeGame.id, engineColor: activeGame.engineColor, createdAt: activeGame.createdAt });
  };

  const handleGameEnd = async (result) => {
    if (!activeGame) return;

    const latestState = loadGame(activeGame.id);
    if (latestState) {
      latestState.result = result;
      saveGame(latestState);
    }
    setActiveGame(prev => ({ ...prev, result }));

    const finishedGame = latestState || { ...activeGame, result };

    setPublishStatus('pending');
    const publishResult = await passkeyPublish(finishedGame);

    if (publishResult.published) {
      setPublishStatus('success');
      markGamePublished(finishedGame.id, publishResult.txHash);
      setTimeout(() => setPublishStatus(null), 4000);
    } else if (['no-contract-address', 'passkey-not-authenticated'].includes(publishResult.reason)) {
      setPublishStatus(null);
    } else {
      setPublishStatus('error');
      setTimeout(() => setPublishStatus(null), 5000);
    }
  };

  const handleBackToList = () => {
    setActiveGame(null);
    setPublishStatus(null);
    setOnlineRoomId(null);
    setOnlineInviteCode(null);
    setView('list');
  };

  // Unauthenticated: show auth gate only
  if (!passkey.isAuthenticated) {
    return <AuthGate onSignup={passkey.signup} onLogin={passkey.login} />;
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>Chess Board</h1>
        <div className="passkey-status">
          <span className="passkey-badge" title={passkey.account}>
            {passkey.username || passkey.account?.slice(0, 6) + '...' + passkey.account?.slice(-4)}
          </span>
          {serverAuth.isConnected && <span className="server-badge">Online</span>}
          <button className="passkey-logout" onClick={handleLogout}>Logout</button>
        </div>
      </header>

      {publishStatus && (
        <div className={`publish-toast ${publishStatus}`}>
          {publishStatus === 'pending' && 'Publishing game on-chain...'}
          {publishStatus === 'success' && 'Game published on-chain!'}
          {publishStatus === 'error' && 'Failed to publish on-chain'}
        </div>
      )}

      {view === 'list' && (
        <GameList onNewGame={handleNewGame} onResumeGame={handleResumeGame} />
      )}

      {view === 'setup' && (
        <GameSetup
          onStartLocal={handleStartLocal}
          onStartOnline={handleStartOnline}
          onJoinGame={handleJoinGame}
          onCancel={() => setView('list')}
          isServerConnected={serverAuth.isConnected}
        />
      )}

      {view === 'join' && (
        <JoinGame
          serverToken={serverAuth.serverToken}
          onJoined={handleJoined}
          onCancel={() => setView('setup')}
        />
      )}

      {view === 'waiting' && (
        <WaitingRoom
          inviteCode={onlineInviteCode}
          serverToken={serverAuth.serverToken}
          roomId={onlineRoomId}
          onGameStart={handleWaitingGameStart}
          onCancel={handleBackToList}
        />
      )}

      {view === 'online' && onlineRoomId && (
        <OnlineChessboard
          key={onlineRoomId}
          serverToken={serverAuth.serverToken}
          roomId={onlineRoomId}
          onBackToList={handleBackToList}
        />
      )}

      {view === 'playing' && activeGame && (
        <Chessboard
          key={activeGame.id}
          initialState={activeGame}
          onSave={handleSave}
          onGameEnd={handleGameEnd}
          onBackToList={handleBackToList}
          engineColorProp={activeGame.engineColor}
        />
      )}
    </div>
  );
}

export default App;

import { useState, useEffect, useCallback } from 'react';
import { PASSKEY_SERVER_URL } from '../config';
const LS_KEYS = {
  credentialId: 'passkey_credentialId',
  rawId: 'passkey_rawId',
  account: 'passkey_account',
};

function bufToHex(buf) {
  return '0x' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

function base64urlEncode(buf) {
  return btoa(String.fromCharCode(...new Uint8Array(buf)))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64urlDecode(str) {
  str = str.replace(/-/g, '+').replace(/_/g, '/');
  while (str.length % 4) str += '=';
  const binary = atob(str);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

export function usePasskeyAuth() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [account, setAccount] = useState(null);
  const [username, setUsername] = useState(null);
  const [credentialId, setCredentialId] = useState(null);
  const [rawId, setRawId] = useState(null);

  // Restore session from localStorage on mount
  useEffect(() => {
    const storedCredId = localStorage.getItem(LS_KEYS.credentialId);
    const storedRawId = localStorage.getItem(LS_KEYS.rawId);
    const storedAccount = localStorage.getItem(LS_KEYS.account);
    if (storedCredId && storedRawId && storedAccount) {
      const parsed = JSON.parse(storedAccount);
      setCredentialId(storedCredId);
      setRawId(base64urlDecode(storedRawId));
      setAccount(parsed.address);
      setUsername(parsed.username);
      setIsAuthenticated(true);
    }
  }, []);

  const persistSession = useCallback((credId, rawIdBuf, address, user) => {
    localStorage.setItem(LS_KEYS.credentialId, credId);
    localStorage.setItem(LS_KEYS.rawId, base64urlEncode(rawIdBuf));
    localStorage.setItem(LS_KEYS.account, JSON.stringify({ address, username: user }));
    setCredentialId(credId);
    setRawId(rawIdBuf);
    setAccount(address);
    setUsername(user);
    setIsAuthenticated(true);
  }, []);

  const signup = useCallback(async (name) => {
    if (!name || !name.trim()) throw new Error('Username required');
    const trimmed = name.trim();

    // 1. Create passkey credential
    const challenge = crypto.getRandomValues(new Uint8Array(32));
    const credential = await navigator.credentials.create({
      publicKey: {
        rp: { name: 'Login.com Smart Account', id: location.hostname },
        user: {
          id: crypto.getRandomValues(new Uint8Array(16)),
          name: trimmed,
          displayName: trimmed,
        },
        challenge,
        pubKeyCredParams: [{ type: 'public-key', alg: -7 }], // ES256 = P-256
        authenticatorSelection: {
          authenticatorAttachment: 'platform',
          residentKey: 'required',
          userVerification: 'preferred',
        },
        timeout: 60000,
      },
    });

    // 2. Extract public key (X, Y)
    const publicKeyBytes = new Uint8Array(credential.response.getPublicKey());
    let rawKey;
    if (publicKeyBytes.length === 65 && publicKeyBytes[0] === 0x04) {
      rawKey = publicKeyBytes;
    } else {
      const spkiOffset = publicKeyBytes.length - 65;
      rawKey = publicKeyBytes.slice(spkiOffset);
    }
    if (rawKey[0] !== 0x04) throw new Error('Expected uncompressed public key (0x04 prefix)');

    const pubKeyX = bufToHex(rawKey.slice(1, 33));
    const pubKeyY = bufToHex(rawKey.slice(33, 65));
    const credId = base64urlEncode(credential.rawId);

    // 3. Register on server (deploys smart account)
    const resp = await fetch(`${API_BASE}/api/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ credentialId: credId, pubKeyX, pubKeyY, username: trimmed }),
    });
    const data = await resp.json();
    if (!resp.ok) throw new Error(data.error || 'Registration failed');

    // 4. Persist session
    persistSession(credId, credential.rawId, data.address, trimmed);
    return { address: data.address, txHash: data.txHash };
  }, [persistSession]);

  const login = useCallback(async () => {
    // 1. Discoverable credential assertion
    const challenge = crypto.getRandomValues(new Uint8Array(32));
    const assertion = await navigator.credentials.get({
      publicKey: {
        challenge,
        rpId: location.hostname,
        allowCredentials: [],
        userVerification: 'preferred',
        timeout: 60000,
      },
    });

    const credId = base64urlEncode(assertion.rawId);

    // 2. Look up account on server
    const resp = await fetch(`${API_BASE}/api/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ credentialId: credId }),
    });
    const data = await resp.json();
    if (!resp.ok) throw new Error(data.error || 'Login failed');

    // 3. Persist session
    persistSession(credId, assertion.rawId, data.accountAddress, data.username);
    return { address: data.accountAddress, username: data.username };
  }, [persistSession]);

  const logout = useCallback(() => {
    localStorage.removeItem(LS_KEYS.credentialId);
    localStorage.removeItem(LS_KEYS.rawId);
    localStorage.removeItem(LS_KEYS.account);
    setCredentialId(null);
    setRawId(null);
    setAccount(null);
    setUsername(null);
    setIsAuthenticated(false);
  }, []);

  return { isAuthenticated, account, username, credentialId, rawId, signup, login, logout };
}

import { useState, useEffect, useCallback } from 'react';
import { GAME_SERVER_URL } from '../config';
const SS_TOKEN_KEY = 'server_auth_token';

export function useServerAuth({ isAuthenticated, account, username }) {
  const [serverToken, setServerToken] = useState(() => sessionStorage.getItem(SS_TOKEN_KEY));
  const [isConnected, setIsConnected] = useState(() => !!sessionStorage.getItem(SS_TOKEN_KEY));

  // When passkey auth state changes, bridge to server token
  useEffect(() => {
    if (!isAuthenticated || !account || !username) {
      setServerToken(null);
      setIsConnected(false);
      sessionStorage.removeItem(SS_TOKEN_KEY);
      return;
    }

    // If we already have a token in this session, skip
    const existing = sessionStorage.getItem(SS_TOKEN_KEY);
    if (existing) {
      setServerToken(existing);
      setIsConnected(true);
      return;
    }

    let cancelled = false;

    async function bridge() {
      try {
        const resp = await fetch(`${SERVER_BASE}/api/auth/token`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ passkeyAddress: account, username }),
        });

        if (!resp.ok) {
          console.error('Server auth bridge failed:', await resp.text());
          return;
        }

        const data = await resp.json();
        if (!cancelled) {
          sessionStorage.setItem(SS_TOKEN_KEY, data.token);
          setServerToken(data.token);
          setIsConnected(true);
        }
      } catch (err) {
        console.error('Server auth bridge error:', err);
        if (!cancelled) {
          setIsConnected(false);
        }
      }
    }

    bridge();
    return () => { cancelled = true; };
  }, [isAuthenticated, account, username]);

  const logout = useCallback(() => {
    sessionStorage.removeItem(SS_TOKEN_KEY);
    setServerToken(null);
    setIsConnected(false);
  }, []);

  return { serverToken, isConnected, logout };
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { GAME_SERVER_URL, GAME_WS_URL } from '../config';

export function useOnlineGame({ serverToken, roomId }) {
  const [board, setBoard] = useState(null);
  const [currentTurn, setCurrentTurn] = useState(null);
  const [myColor, setMyColor] = useState(null);
  const [legalMoves, setLegalMoves] = useState([]);
  const [moveHistory, setMoveHistory] = useState([]);
  const [gameResult, setGameResult] = useState(null);
  const [status, setStatus] = useState('loading'); // loading | waiting | playing | finished | error
  const [room, setRoom] = useState(null);
  const [error, setError] = useState(null);

  const wsRef = useRef(null);
  const roomIdRef = useRef(roomId);
  roomIdRef.current = roomId;

  const headers = useCallback(() => ({
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${serverToken}`,
  }), [serverToken]);

  // Fetch room state from server
  const fetchRoom = useCallback(async () => {
    if (!serverToken || !roomId) return;

    try {
      const resp = await fetch(`${SERVER_BASE}/api/rooms/${roomId}`, {
        headers: { 'Authorization': `Bearer ${serverToken}` },
      });

      if (!resp.ok) {
        const data = await resp.json().catch(() => ({}));
        setError(data.error || 'Failed to fetch room');
        setStatus('error');
        return;
      }

      const data = await resp.json();
      setBoard(data.board);
      setCurrentTurn(data.currentTurn);
      setMyColor(data.myColor);
      setLegalMoves(data.legalMoves || []);
      setMoveHistory(data.moveHistory || []);
      setRoom(data);

      if (data.result) {
        setGameResult(data.result);
        setStatus('finished');
      } else if (data.status === 'waiting') {
        setStatus('waiting');
      } else {
        setStatus('playing');
      }
    } catch (err) {
      console.error('Fetch room error:', err);
      setError('Network error');
      setStatus('error');
    }
  }, [serverToken, roomId]);

  // Initial fetch
  useEffect(() => {
    fetchRoom();
  }, [fetchRoom]);

  // WebSocket connection
  useEffect(() => {
    if (!serverToken || !roomId) return;

    const ws = new WebSocket(`${WS_BASE}/api/rooms/${roomId}/ws?token=${serverToken}`);
    wsRef.current = ws;

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);

      switch (msg.event) {
        case 'joined':
          // Our own connection confirmed
          break;

        case 'join':
          // Another player joined - game is starting
          setStatus('playing');
          fetchRoom();
          break;

        case 'move':
          // Opponent made a move - re-fetch full state for legal moves
          fetchRoom();
          break;

        case 'gameOver':
          setGameResult(msg.data.result);
          setStatus('finished');
          fetchRoom();
          break;

        case 'playerConnected':
        case 'playerDisconnected':
          // Could show connection indicators later
          break;
      }
    };

    ws.onerror = (err) => {
      console.error('WebSocket error:', err);
    };

    ws.onclose = () => {
      wsRef.current = null;
    };

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [serverToken, roomId, fetchRoom]);

  // Submit a move via REST
  const submitMove = useCallback(async (uciStr) => {
    if (!serverToken || !roomId) return { ok: false };

    try {
      const resp = await fetch(`${SERVER_BASE}/api/rooms/${roomId}/move`, {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify({ move: uciStr }),
      });

      const data = await resp.json();

      if (!resp.ok) {
        console.error('Move rejected:', data.error);
        return { ok: false, error: data.error };
      }

      // Re-fetch to get updated board and legal moves
      await fetchRoom();

      if (data.gameOver) {
        setGameResult(data.result);
        setStatus('finished');
      }

      return { ok: true, data };
    } catch (err) {
      console.error('Submit move error:', err);
      return { ok: false, error: 'Network error' };
    }
  }, [serverToken, roomId, headers, fetchRoom]);

  // Get valid target squares for a source square from server legal moves
  const getValidMovesForSquare = useCallback((sourceIndex) => {
    const cols = 'abcdefgh';
    const sourceFile = cols[sourceIndex % 8];
    const sourceRank = 8 - Math.floor(sourceIndex / 8);
    const sourceStr = sourceFile + sourceRank;

    const targets = [];
    for (const uci of legalMoves) {
      if (uci.startsWith(sourceStr)) {
        const targetFile = uci[2];
        const targetRank = parseInt(uci[3]);
        const targetCol = cols.indexOf(targetFile);
        const targetRow = 8 - targetRank;
        const targetIndex = targetRow * 8 + targetCol;
        targets.push(targetIndex);
      }
    }

    // Deduplicate (promotions create multiple moves for same target)
    return [...new Set(targets)];
  }, [legalMoves]);

  return {
    board,
    currentTurn,
    myColor,
    legalMoves,
    moveHistory,
    gameResult,
    status,
    error,
    room,
    submitMove,
    getValidMovesForSquare,
    fetchRoom,
  };
}

