  useEffect(() => {
    if (!serverToken || !roomId) return;

    const ws = new WebSocket(`${WS_BASE}/api/rooms/${roomId}/ws?token=${serverToken}`);
    wsRef.current = ws;

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);

      switch (msg.event) {
        case 'joined':
          // Our own connection confirmed
          break;

        case 'join':
          // Another player joined - game is starting
          setStatus('playing');
          fetchRoom();
          break;

        case 'move':
          // Opponent made a move - re-fetch full state for legal moves
          fetchRoom();
          break;

        case 'gameOver':
          setGameResult(msg.data.result);
          setStatus('finished');
          fetchRoom();
          break;

        case 'playerConnected':
        case 'playerDisconnected':
          // Could show connection indicators later
          break;
      }
    };

    ws.onerror = (err) => {
      console.error('WebSocket error:', err);
    };

    ws.onclose = () => {
      wsRef.current = null;
    };

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [serverToken, roomId, fetchRoom]);

  // Submit a move via REST
  const submitMove = useCallback(async (uciStr) => {
    if (!serverToken || !roomId) return { ok: false };

    try {
      const resp = await fetch(`${GAME_SERVER_URL}/api/rooms/${roomId}/move`, {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify({ move: uciStr }),
      });

      const data = await resp.json();

      if (!resp.ok) {
        console.error('Move rejected:', data.error);
        return { ok: false, error: data.error };
      }

      // Re-fetch to get updated board and legal moves
      await fetchRoom();

      if (data.gameOver) {
        setGameResult(data.result);
        setStatus('finished');
      }

      return { ok: true, data };
    } catch (err) {
      console.error('Submit move error:', err);
      return { ok: false, error: 'Network error' };
    }
  }, [serverToken, roomId, headers, fetchRoom]);

  // Get valid target squares for a source square from server legal moves
  const getValidMovesForSquare = useCallback((sourceIndex) => {
    const cols = 'abcdefgh';
    const sourceFile = cols[sourceIndex % 8];
    const sourceRank = 8 - Math.floor(sourceIndex / 8);
    const sourceStr = sourceFile + sourceRank;

    const targets = [];
    for (const uci of legalMoves) {
      if (uci.startsWith(sourceStr)) {
        const targetFile = uci[2];
        const targetRank = parseInt(uci[3]);
        const targetCol = cols.indexOf(targetFile);
        const targetRow = 8 - targetRank;
        const targetIndex = targetRow * 8 + targetCol;
        targets.push(targetIndex);
      }
    }

    // Deduplicate (promotions create multiple moves for same target)
    return [...new Set(targets)];
  }, [legalMoves]);

  return {
    board,
    currentTurn,
    myColor,
    legalMoves,
    moveHistory,
    gameResult,
    status,
    error,
    room,
    submitMove,
    getValidMovesForSquare,
    fetchRoom,
  };
}

import { useCallback } from 'react';
import { encodeFunctionData } from 'viem';
import { formatMoves } from './usePublishGame';
import { chessLedgerAbi, CHESS_LEDGER_ADDRESS } from '../contracts/chessLedgerAbi';
import { PASSKEY_SERVER_URL } from '../config';

// --- Helpers (ported from demo.html) ---

function bufToHex(buf) {
  return '0x' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

function hexToBytes(hex) {
  hex = hex.startsWith('0x') ? hex.slice(2) : hex;
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
  }
  return bytes;
}

function parseDERSignature(signatureBytes) {
  const sig = new Uint8Array(signatureBytes);
  let offset = 0;

  if (sig[offset++] !== 0x30) throw new Error('Invalid DER: missing SEQUENCE tag');
  let totalLen = sig[offset++];
  if (totalLen & 0x80) {
    const numLenBytes = totalLen & 0x7f;
    offset += numLenBytes;
  }

  // R
  if (sig[offset++] !== 0x02) throw new Error('Invalid DER: missing INTEGER tag for r');
  const rLen = sig[offset++];
  let rBytes = sig.slice(offset, offset + rLen);
  offset += rLen;
  while (rBytes.length > 32 && rBytes[0] === 0x00) rBytes = rBytes.slice(1);
  if (rBytes.length < 32) {
    const padded = new Uint8Array(32);
    padded.set(rBytes, 32 - rBytes.length);
    rBytes = padded;
  }

  // S
  if (sig[offset++] !== 0x02) throw new Error('Invalid DER: missing INTEGER tag for s');
  const sLen = sig[offset++];
  let sBytes = sig.slice(offset, offset + sLen);
  while (sBytes.length > 32 && sBytes[0] === 0x00) sBytes = sBytes.slice(1);
  if (sBytes.length < 32) {
    const padded = new Uint8Array(32);
    padded.set(sBytes, 32 - sBytes.length);
    sBytes = padded;
  }

  return { r: bufToHex(rBytes), s: bufToHex(sBytes) };
}

// --- Hook ---

export function usePasskeyPublish({ account, credentialId, rawId }) {
  const publishGame = useCallback(async (game) => {
    if (!account || !rawId) {
      return { published: false, reason: 'passkey-not-authenticated' };
    }
    if (!CHESS_LEDGER_ADDRESS) {
      return { published: false, reason: 'no-contract-address' };
    }

    try {
      // 1. Encode ChessLedger.publishGame calldata
      const movesString = formatMoves(game.moveHistory || []);
      const calldata = encodeFunctionData({
        abi: chessLedgerAbi,
        functionName: 'publishGame',
        args: [game.id, game.result, movesString, game.engineColor],
      });

      // 2. Get challenge from server
      const challengeResp = await fetch(`${API_BASE}/api/get-challenge-v2`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          proxyAddr: account,
          target: CHESS_LEDGER_ADDRESS,
          value: '0',
          data: calldata,
        }),
      });
      const challengeData = await challengeResp.json();
      if (!challengeResp.ok) throw new Error(challengeData.error || 'Failed to get challenge');

      const challengeBytes = hexToBytes(challengeData.challenge);

      // 3. Sign with passkey (raw challenge bytes — NOT base64)
      const assertion = await navigator.credentials.get({
        publicKey: {
          challenge: challengeBytes,
          rpId: location.hostname,
          allowCredentials: [{ type: 'public-key', id: rawId }],
          userVerification: 'preferred',
          timeout: 60000,
        },
      });

      // 4. Extract signature fields
      const authenticatorData = bufToHex(assertion.response.authenticatorData);
      const clientDataJSON = new TextDecoder().decode(assertion.response.clientDataJSON);
      const { r, s } = parseDERSignature(new Uint8Array(assertion.response.signature));
      const typeIndex = clientDataJSON.indexOf('"type":"webauthn.get"');
      const challengeIndex = clientDataJSON.indexOf('"challenge":"');

      // 5. Submit signed transaction
      const submitResp = await fetch(`${API_BASE}/api/submit-execution-v2`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          proxyAddr: account,
          target: CHESS_LEDGER_ADDRESS,
          value: '0',
          data: calldata,
          auth: { authenticatorData, clientDataJSON, challengeIndex, typeIndex, r, s },
        }),
      });
      const txData = await submitResp.json();
      if (!submitResp.ok) throw new Error(txData.error || 'Failed to submit transaction');

      return { published: true, txHash: txData.txHash };
    } catch (err) {
      console.error('Passkey publish failed:', err);
      return { published: false, reason: 'tx-failed', error: err };
    }
  }, [account, credentialId, rawId]);

  return { publishGame };
}

import { useState } from 'react';
import { GAME_SERVER_URL } from '../config';

function JoinGame({ serverToken, onJoined, onCancel }) {
  const [inviteCode, setInviteCode] = useState('');
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleJoin = async () => {
    const code = inviteCode.trim().toUpperCase();
    if (!code) {
      setError('Enter an invite code');
      return;
    }

    setError(null);
    setLoading(true);

    try {
      const resp = await fetch(`${SERVER_BASE}/api/rooms/join`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${serverToken}`,
        },
        body: JSON.stringify({ inviteCode: code }),
      });

      const data = await resp.json();

      if (!resp.ok) {
        setError(data.error || 'Failed to join room');
        setLoading(false);
        return;
      }

      onJoined(data.roomId, data.color);
    } catch (err) {
      setError('Network error — is the server running?');
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') handleJoin();
  };

  return (
    <div className="new-game-setup">
      <h2>Join Game</h2>

      <div className="join-form">
        <label>Invite Code:</label>
        <input
          type="text"
          className="join-input"
          value={inviteCode}
          onChange={(e) => setInviteCode(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="e.g. ROOK42"
          autoFocus
          maxLength={10}
        />
      </div>

      {error && <div className="join-error">{error}</div>}

      <div className="setup-actions">
        <button className="setup-back" onClick={onCancel}>Cancel</button>
        <button className="setup-start" onClick={handleJoin} disabled={loading}>
          {loading ? 'Joining...' : 'Join'}
        </button>
      </div>
    </div>
  );
}

export default JoinGame;

import { useState, useEffect, useRef } from 'react';
import { GAME_WS_URL } from '../config';

function WaitingRoom({ inviteCode, serverToken, roomId, onGameStart, onCancel }) {
  const [copied, setCopied] = useState(false);
  const wsRef = useRef(null);

  useEffect(() => {
    if (!serverToken || !roomId) return;

    const ws = new WebSocket(`${WS_BASE}/api/rooms/${roomId}/ws?token=${serverToken}`);
    wsRef.current = ws;

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.event === 'join') {
        onGameStart(roomId);
      }
    };

    ws.onerror = (err) => {
      console.error('WaitingRoom WS error:', err);
    };

    ws.onclose = () => {
      wsRef.current = null;
    };

    return () => {
      ws.close();
      wsRef.current = null;
    };
  }, [serverToken, roomId, onGameStart]);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(inviteCode);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback for non-HTTPS
      const el = document.createElement('textarea');
      el.value = inviteCode;
      document.body.appendChild(el);
      el.select();
      document.execCommand('copy');
      document.body.removeChild(el);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="new-game-setup waiting-room">
      <h2>Waiting for Opponent</h2>

      <p className="waiting-subtitle">Share this code with your opponent:</p>

      <div className="invite-code-display">
        <span className="invite-code">{inviteCode}</span>
        <button className="copy-button" onClick={handleCopy}>
          {copied ? 'Copied!' : 'Copy'}
        </button>
      </div>

      <p className="waiting-hint">The game will start automatically when they join.</p>

      <div className="setup-actions">
        <button className="setup-back" onClick={onCancel}>Cancel</button>
      </div>
    </div>
  );
}

export default WaitingRoom;

import { useState, useEffect } from 'react';

import './App.css';
import Chessboard from './Chessboard';
import GameList from './components/GameList';
import AuthGate from './components/AuthGate';
import GameSetup from './components/GameSetup';
import JoinGame from './components/JoinGame';
import WaitingRoom from './components/WaitingRoom';
import OnlineChessboard from './components/OnlineChessboard';
import { createGame, saveGame, loadGame, markGamePublished, setCurrentUser } from './utils/gameManager';
import { usePasskeyAuth } from './hooks/usePasskeyAuth';
import { usePasskeyPublish } from './hooks/usePasskeyPublish';
import { useServerAuth } from './hooks/useServerAuth';
import { GAME_SERVER_URL } from './config';

// Persist/restore online game session across reloads
const SS_ONLINE_KEY = 'online_game_session';

function saveOnlineSession(view, roomId, inviteCode) {
  if (view === 'online' || view === 'waiting') {
    sessionStorage.setItem(SS_ONLINE_KEY, JSON.stringify({ view, roomId, inviteCode }));
  } else {
    sessionStorage.removeItem(SS_ONLINE_KEY);
  }
}

function loadOnlineSession() {
  try {
    const raw = sessionStorage.getItem(SS_ONLINE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch { return null; }
}

function App() {
  const saved = loadOnlineSession();
  const [view, setView] = useState(saved?.view || 'list');
  const [activeGame, setActiveGame] = useState(null);
  const [publishStatus, setPublishStatus] = useState(null);

  // Online game state
  const [onlineRoomId, setOnlineRoomId] = useState(saved?.roomId || null);
  const [onlineInviteCode, setOnlineInviteCode] = useState(saved?.inviteCode || null);

  const passkey = usePasskeyAuth();
  const serverAuth = useServerAuth({
    isAuthenticated: passkey.isAuthenticated,
    account: passkey.account,
    username: passkey.username,
  });
  const { publishGame: passkeyPublish } = usePasskeyPublish({
    account: passkey.account,
    credentialId: passkey.credentialId,
    rawId: passkey.rawId,
  });

  // Persist online session to sessionStorage on state changes
  useEffect(() => {
    saveOnlineSession(view, onlineRoomId, onlineInviteCode);
  }, [view, onlineRoomId, onlineInviteCode]);

  // Scope game storage to the authenticated user
  useEffect(() => {
    if (passkey.isAuthenticated && passkey.account) {
      setCurrentUser(passkey.account);
    } else {
      setCurrentUser(null);
    }
  }, [passkey.isAuthenticated, passkey.account]);

  const handleLogout = () => {
    passkey.logout();
    serverAuth.logout();
    setActiveGame(null);
    setPublishStatus(null);
    setOnlineRoomId(null);
    setOnlineInviteCode(null);
    setView('list');
  };

  const handleNewGame = () => {
    setView('setup');
  };

  // Local AI game start
  const handleStartLocal = (color) => {
    const engineColor = color === 'white' ? 'black' : 'white';
    const game = createGame(engineColor);
    setActiveGame(game);
    setView('playing');
  };

  // Online game start
  const handleStartOnline = async (color) => {
    if (!serverAuth.serverToken) return;

    try {
      const resp = await fetch(`${SERVER_BASE}/api/rooms`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${serverAuth.serverToken}`,
        },
        body: JSON.stringify({ color, opponent: 'human' }),
      });

      const data = await resp.json();
      if (!resp.ok) {
        console.error('Create room failed:', data.error);
        return;
      }

      setOnlineRoomId(data.roomId);
      setOnlineInviteCode(data.inviteCode);
      setView('waiting');
    } catch (err) {
      console.error('Create room error:', err);
    }
  };

  const handleJoinGame = () => {
    setView('join');
  };

  const handleJoined = (roomId) => {
    setOnlineRoomId(roomId);
    setView('online');
  };

  const handleWaitingGameStart = (roomId) => {
    setOnlineRoomId(roomId);
    setView('online');
  };

  const handleResumeGame = (gameId) => {
    const game = loadGame(gameId);
    if (game) {
      setActiveGame(game);
      setView('playing');
    }
  };

  const handleSave = (state) => {
    if (!activeGame) return;
    saveGame({ ...state, id: activeGame.id, engineColor: activeGame.engineColor, createdAt: activeGame.createdAt });
  };

  const handleGameEnd = async (result) => {
    if (!activeGame) return;

    const latestState = loadGame(activeGame.id);
    if (latestState) {
      latestState.result = result;
      saveGame(latestState);
    }
    setActiveGame(prev => ({ ...prev, result }));

    const finishedGame = latestState || { ...activeGame, result };

    setPublishStatus('pending');
    const publishResult = await passkeyPublish(finishedGame);

    if (publishResult.published) {
      setPublishStatus('success');
      markGamePublished(finishedGame.id, publishResult.txHash);
      setTimeout(() => setPublishStatus(null), 4000);
    } else if (['no-contract-address', 'passkey-not-authenticated'].includes(publishResult.reason)) {
      setPublishStatus(null);
    } else {
      setPublishStatus('error');
      setTimeout(() => setPublishStatus(null), 5000);
    }
  };

  const handleBackToList = () => {
    setActiveGame(null);
    setPublishStatus(null);
    setOnlineRoomId(null);
    setOnlineInviteCode(null);
    setView('list');
  };

  // Unauthenticated: show auth gate only
  if (!passkey.isAuthenticated) {
    return <AuthGate onSignup={passkey.signup} onLogin={passkey.login} />;
  }

  return (
    <div className="app">
      <header className="app-header">
        <h1>Chess Board</h1>
        <div className="passkey-status">
          <span className="passkey-badge" title={passkey.account}>
            {passkey.username || passkey.account?.slice(0, 6) + '...' + passkey.account?.slice(-4)}
          </span>
          {serverAuth.isConnected && <span className="server-badge">Online</span>}
          <button className="passkey-logout" onClick={handleLogout}>Logout</button>
        </div>
      </header>

      {publishStatus && (
        <div className={`publish-toast ${publishStatus}`}>
          {publishStatus === 'pending' && 'Publishing game on-chain...'}
          {publishStatus === 'success' && 'Game published on-chain!'}
          {publishStatus === 'error' && 'Failed to publish on-chain'}
        </div>
      )}

      {view === 'list' && (
        <GameList onNewGame={handleNewGame} onResumeGame={handleResumeGame} />
      )}

      {view === 'setup' && (
        <GameSetup
          onStartLocal={handleStartLocal}
          onStartOnline={handleStartOnline}
          onJoinGame={handleJoinGame}
          onCancel={() => setView('list')}
          isServerConnected={serverAuth.isConnected}
        />
      )}

      {view === 'join' && (
        <JoinGame
          serverToken={serverAuth.serverToken}
          onJoined={handleJoined}
          onCancel={() => setView('setup')}
        />
      )}

      {view === 'waiting' && (
        <WaitingRoom
          inviteCode={onlineInviteCode}
          serverToken={serverAuth.serverToken}
          roomId={onlineRoomId}
          onGameStart={handleWaitingGameStart}
          onCancel={handleBackToList}
        />
      )}

      {view === 'online' && onlineRoomId && (
        <OnlineChessboard
          key={onlineRoomId}
          serverToken={serverAuth.serverToken}
          roomId={onlineRoomId}
          onBackToList={handleBackToList}
        />
      )}

      {view === 'playing' && activeGame && (
        <Chessboard
          key={activeGame.id}
          initialState={activeGame}
          onSave={handleSave}
          onGameEnd={handleGameEnd}
          onBackToList={handleBackToList}
          engineColorProp={activeGame.engineColor}
        />
      )}
    </div>
  );
}

export default App;

